) %}


<!-- ================================= -->
<!-- CALCULATE HEADING TOTALS -->
<!-- ================================= -->

{% for heading_item in doc.invoice_list_items %}

    {% set heading = heading_item.heading %}

    {% if heading and heading not in ns.processed_headings %}

        {% set ns.processed_headings =
            ns.processed_headings + [heading] %}

        {% set heading_ns = namespace(
            subtotal=0
        ) %}


        {% for invoice_row in doc.invoice_list_items %}

            {% if invoice_row.heading == heading
                and invoice_row.invoice_number %}

                {% set invoice = frappe.get_doc(
                    "Sales Invoice",
                    invoice_row.invoice_number
                ) %}


                <!-- INVOICE ITEMS -->

                {% for invoice_item in invoice.items %}

                    {% set heading_ns.subtotal =
                        heading_ns.subtotal
                        + (invoice_item.amount or 0) %}

                {% endfor %}


                <!-- ADD TAXES AND CHARGES -->

                {% set heading_ns.subtotal =
                    heading_ns.subtotal
                    + (invoice.total_taxes_and_charges or 0) %}

            {% endif %}

        {% endfor %}


        <!-- SAVE HEADING SUBTOTAL -->

        {% set ns.heading_subtotals =
            ns.heading_subtotals + [
                {
                    "heading": heading,
                    "subtotal": heading_ns.subtotal
                }
            ]
        %}


        <!-- GRAND TOTAL -->

        {% set ns.grand_total =
            ns.grand_total + heading_ns.subtotal %}

    {% endif %}

{% endfor %}


<!-- ================================= -->
<!-- TOP HEADING SUBTOTAL SUMMARY -->
<!-- ================================= -->

<table style="width:100%; border-collapse:collapse; margin-bottom:20px;">

    {% for item in ns.heading_subtotals %}

        <tr>

            <td colspan="7"
                style="
                    text-align:left;
                    padding:3px 8px;
                    font-size:11px;
                ">

                {{ item.heading }} Subtotal

            </td>

            <td
                style="
                    text-align:right;
                    padding:3px 8px;
                    font-size:11px;
                ">

                {{ frappe.utils.fmt_money(
                    item.subtotal,
                    currency=doc.currency
                ) }}

            </td>

        </tr>

    {% endfor %}

</table>


