                    {% if customer_row.heading == heading
                        and customer_row.invoice_number %}

                        {% set customer_invoice = frappe.get_doc(
                            "Sales Invoice",
                            customer_row.invoice_number
                        ) %}


                        {% set customer =
                            customer_invoice.customer_name %}


                        {% if customer not in customers_ns.customers %}

                            {% set customers_ns.customers =
                                customers_ns.customers + [customer] %}

                        {% endif %}

                    {% endif %}

                {% endfor %}


                <!-- ================================= -->
                <!-- CUSTOMERS -->
                <!-- ================================= -->

                {% for customer in customers_ns.customers %}

                    {% set customer_ns = namespace(
                        subtotal=0,
                        taxes=0
                    ) %}


                    {% for invoice_row in doc.invoice_list_items %}

                        {% if invoice_row.heading == heading
                            and invoice_row.invoice_number %}

                            {% set invoice = frappe.get_doc(
                                "Sales Invoice",
                                invoice_row.invoice_number
                            ) %}


                            {% if invoice.customer_name == customer %}


                                <!-- INVOICE ITEMS -->

                                {% for invoice_item in invoice.items %}

                                    {% set display_ns.counter =
                                        display_ns.counter + 1 %}


                                    <tr>

                                        <td style="text-align:center;">
                                            {{ display_ns.counter }}
                                        </td>

                                        <td>
                                            {{ invoice.customer_name }}
                                        </td>

                                        <td>
                                            {{ invoice_item.description }}
                                        </td>

                                        <td>
                                            {{ invoice.name }}
                                        </td>

                                        <td style="text-align:center;">
                                            {{ invoice_item.uom }}
                                        </td>

                                        <td style="text-align:right;">
                                            {{ invoice_item.qty }}
                                        </td>

                                        <td style="text-align:right;">
                                            {{ frappe.utils.fmt_money(
                                                invoice_item.rate,
                                                currency=invoice.currency
                                            ) }}
                                        </td>

                                        <td style="text-align:right;">
                                            {{ frappe.utils.fmt_money(
                                                invoice_item.amount,
                                                currency=invoice.currency
                                            ) }}
                                        </td>

                                    </tr>


                                    <!-- CUSTOMER ITEM SUBTOTAL -->

                                    {% set customer_ns.subtotal =
                                        customer_ns.subtotal
                                        + (invoice_item.amount or 0) %}

                                {% endfor %}


                                <!-- CUSTOMER TAXES -->

                                {% set customer_ns.taxes =
                                    customer_ns.taxes
                                    + (invoice.total_taxes_and_charges or 0) %}


                            {% endif %}

                        {% endif %}

                    {% endfor %}


                    <!-- ================================= -->
                    <!-- CUSTOMER SUBTOTAL + TAXES -->
                    <!-- ================================= -->

                    {% set customer_total =
                        customer_ns.subtotal
                        + customer_ns.taxes %}


                    <tr>

                        <th colspan="7"
                            style="
                                text-align:right;
                                font-size:11px;
                            ">

                            {{ customer }}
                            Subtotal + Taxes & Charges

                        </th>

                        <th
                            style="
                                text-align:right;
                                font-size:11px;
                            ">

                            {{ frappe.utils.fmt_money(
                                customer_total,
                                currency=doc.currency
                            ) }}

                        </th>

                    </tr>


                {% endfor %}


                <!-- ================================= -->
                <!-- HEADING SUBTOTAL -->
                <!-- ================================= -->

                {% set display_heading_ns = namespace(
                    subtotal=0
                ) %}


                {% for invoice_row in doc.invoice_list_items %}

                    {% if invoice_row.heading == heading
