                        {% set invoice = frappe.get_doc(
                            "Sales Invoice",
                            invoice_row.invoice_number
                        ) %}


                        {% for invoice_item in invoice.items %}

                            {% set display_heading_ns.subtotal =
                                display_heading_ns.subtotal
                                + (invoice_item.amount or 0) %}

                        {% endfor %}


                        {% set display_heading_ns.subtotal =
                            display_heading_ns.subtotal
                            + (invoice.total_taxes_and_charges or 0) %}

                    {% endif %}

                {% endfor %}


                {% if heading %}

                    <tr>

                        <th colspan="7"
                            style="
                                text-align:right;
                                font-size:11px;
                            ">

                            {{ heading }} Subtotal

                        </th>

                        <th
                            style="
                                text-align:right;
                                font-size:11px;
                            ">

                            {{ frappe.utils.fmt_money(
                                display_heading_ns.subtotal,
                                currency=doc.currency
                            ) }}

                        </th>

                    </tr>

                {% endif %}


            {% endif %}

        {% endfor %}

    </tbody>

